const ollamaResp = $input.first().json;
const raw = ollamaResp?.message?.content || '';

// Retrieve original job fields from the node that built the payload
const job = $('Code: Build Ollama Payload').first().json;

if (!raw) {
  console.log('[Evaluate] Empty Ollama response, skipping');
  return [];
}

let parsed;
try {
  const cleaned = raw.replace(/```json\s*/gi, '').replace(/```\s*/gi, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  console.log(`[Evaluate] JSON parse error: ${raw.substring(0, 200)}`);
  return [];
}

if (typeof parsed.match !== 'boolean') {
  console.log(`[Evaluate] Unexpected shape: ${JSON.stringify(parsed)}`);
  return [];
}

console.log(`[Evaluate] ${parsed.match ? '✅ MATCH' : '❌ skip'} — ${parsed.reason}`);

return [{
  json: {
    id:        job.id,
    title:     job.title,
    company:   job.company,
    url:       job.url,
    body:      job.body,
    source:    job.source,
    location:  job.location,
    salary:    job.salary,
    tags:      job.tags,
    scrapedAt: job.scrapedAt,
    match:     parsed.match,
    reason:    parsed.reason,
  }
}];
